<script setup>
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {MapPin,ChevronDown,ArrowRight,Search,ShoppingBag,Heart,Star,Clock,SlidersHorizontal,X,Plus,Minus,ArrowUpRight,Check,Store,Utensils,Ticket,LogOut} from 'lucide-vue-next'
import {useCart} from './store'
import {restaurants,photo} from './data'
import {reverseGeocode} from './geolocation'
const cart=useCart(),query=ref(''),category=ref('Tudo'),filter=ref(''),tab=ref('Explorar'),selected=ref(null),drawer=ref(false),address=ref(sessionStorage.getItem('deliveryAddress')||''),addressOpen=ref(false),loginOpen=ref(false),email=ref(''),password=ref(''),token=ref(sessionStorage.getItem('token')||''),message=ref(''),orders=ref([]),favorites=ref(JSON.parse(localStorage.getItem('rango-favorites')||'[]')),pending=ref(null),online=ref(false),merchant=ref(false)
watch(favorites,value=>localStorage.setItem('rango-favorites',JSON.stringify(value)),{deep:true})
const categories=[['🍽️','Tudo'],['🍔','Hambúrgueres'],['🍕','Pizzas'],['🍣','Japonesa'],['🥗','Saudável'],['🍝','Massas'],['🍰','Doces'],['🥤','Bebidas']]
const money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'})
const visible=computed(()=>restaurants.filter(r=>!r.closed&&(category.value==='Tudo'||r.category===category.value)&&r.name.toLowerCase().includes(query.value.toLowerCase())&&(filter.value!=='Entrega grátis'||!r.fee)&&(filter.value!=='Até 30 min'||parseInt(r.time)<=25)&&(tab.value!=='Favoritos'||favorites.value.includes(r.id))).sort((a,b)=>filter.value==='Melhor avaliação'?Number(b.rating.replace(',','.'))-Number(a.rating.replace(',','.')):0))
function add(p,r){if(!cart.add(p,r.id))pending.value={p,r};else message.value='Adicionado à sua sacola'}
function replace(){cart.clear();cart.add(pending.value.p,pending.value.r.id);pending.value=null}
async function api(path,options={}){const response=await fetch('/api/'+path,{...options,headers:{'Content-Type':'application/json',...(token.value?{Authorization:'Bearer '+token.value}:{}),...options.headers}});const data=await response.json();if(response.status===401&&sessionStorage.getItem('refresh')&&!options.retried){const refreshResponse=await fetch('/api/token/refresh/',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({refresh:sessionStorage.getItem('refresh')})});if(refreshResponse.ok){token.value=(await refreshResponse.json()).access;sessionStorage.setItem('token',token.value);return api(path,{...options,retried:true})}}if(response.status===401){token.value='';accountName.value='';['token','refresh','username'].forEach(key=>sessionStorage.removeItem(key));orders.value=[];merchant.value=false;sockets.forEach(socket=>socket.close());sockets=[];message.value='Sua sess\u00e3o expirou. Entre novamente.'}if(!response.ok)throw new Error(data.detail||JSON.stringify(data));return data}
const loggingIn=ref(false),loginError=ref(''),accountName=ref(sessionStorage.getItem('username')||'')
async function login(){if(loggingIn.value)return;loggingIn.value=true;loginError.value='';try{const response=await fetch('/api/token/',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:email.value.trim(),password:password.value}),signal:AbortSignal.timeout(10000)});if(!response.ok)throw new Error(response.status===401?'Usuário ou senha incorretos.':'Não foi possível entrar. Tente novamente.');const data=await response.json();token.value=data.access;accountName.value=email.value.trim();sessionStorage.setItem('token',data.access);sessionStorage.setItem('refresh',data.refresh);sessionStorage.setItem('username',accountName.value);password.value='';loginOpen.value=false;message.value=`Bem-vindo, ${accountName.value}!`;await loadOrders();orders.value.filter(o=>o.status!=='delivered').forEach(track)}catch(error){loginError.value=error.name==='TimeoutError'?'A API demorou para responder. Tente novamente.':error.message}finally{loggingIn.value=false}}
function logout(){token.value='';accountName.value='';['token','refresh','username'].forEach(key=>sessionStorage.removeItem(key));sockets.forEach(s=>s.close());sockets=[];orders.value=[];merchant.value=false;loginError.value='';loginOpen.value=false;message.value='Você saiu da conta.'}
const ordersLoading=ref(false),ordersError=ref('')
async function loadOrders(){ordersError.value='';if(!token.value){orders.value=[];return}ordersLoading.value=true;try{const data=await api(merchant.value?'orders/?merchant=1':'orders/');orders.value=data.results||data;orderPage.value=1;hasMoreOrders.value=!!data.next}catch{if(token.value)ordersError.value='Não foi possível carregar os pedidos. Tente novamente.'}finally{ordersLoading.value=false}}
let sockets=[]
function track(order){const socket=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/ws/orders/${order.id}/?token=${token.value}`);socket.onmessage=e=>{const event=JSON.parse(e.data);const found=orders.value.find(o=>o.id===event.id);if(found)found.status=event.status};sockets.push(socket)}
async function checkout(){if(!coordinates.value){addressOpen.value=true;message.value='Use sua localização para calcular o frete antes de confirmar.';return}if(!token.value){loginOpen.value=true;return}try{const restaurant=restaurants.find(r=>r.id===cart.items[0]?.restaurant);const order=await api('orders/',{method:'POST',body:JSON.stringify({restaurant:restaurant.id,address:address.value,...coordinates.value,items:cart.items.map(i=>({product:i.productId||i.id,quantity:i.quantity,options:i.optionIds||[]}))})});orders.value.unshift(order);track(order);cart.clear();drawer.value=false;tab.value='Meus pedidos';message.value='Pedido enviado! Acompanhe por aqui.'}catch(e){message.value='Não foi possível concluir: '+e.message}}
async function changeStatus(order){const states=['pending','preparing','out_for_delivery','delivered'];try{const updated=await api(`orders/${order.id}/status/`,{method:'POST',body:JSON.stringify({status:states[states.indexOf(order.status)+1]})});Object.assign(order,updated)}catch{message.value='Não foi possível alterar o status.'}}
function reorder(order){const r=restaurants.find(r=>r.id===order.restaurant);if(!r)return;if(cart.count){message.value='Esvazie a sacola antes de pedir novamente.';drawer.value=true;return}const lines=[];for(const line of order.items){const p=r.products.find(p=>p.id===line.product&&p.available!==false);if(!p){message.value='Um produto não está mais disponível.';return}const options=(line.options_snapshot||[]).map(o=>(p.options||[]).find(current=>current.id===o.id&&current.available));if(options.some(o=>!o)){message.value='Um adicional não está mais disponível.';return}lines.push({...p,id:p.id+':'+options.map(o=>o.id).sort().join(','),productId:p.id,optionIds:options.map(o=>o.id),price:p.price+options.reduce((sum,o)=>sum+Number(o.price),0),quantity:line.quantity,restaurant:r.id})}cart.items=lines;cart.persist();drawer.value=true}
const statusLabels={pending:'Pendente',preparing:'Em preparo',out_for_delivery:'Saiu para entrega',delivered:'Entregue'}
const merchantProducts=ref([]),newName=ref(''),newPrice=ref(''),merchantRestaurant=ref(1),chosenOptions=ref({}),coordinates=ref(null)
const locating=ref(false),locationError=ref(''),locationAccuracy=ref(null),locatedStreet=ref(''),locatedArea=ref(''),locationStage=ref('')
const locationLabel=computed(()=>coordinates.value?`Localização atual (${coordinates.value.latitude.toFixed(4)}, ${coordinates.value.longitude.toFixed(4)})`:'Selecione seu endereço')
function saveAddress(){if(!address.value.trim()){locationError.value='Informe a rua e o número para a entrega.';return}sessionStorage.setItem('deliveryAddress',address.value.trim());addressOpen.value=false}
let catalogTimer
const orderPage=ref(1),hasMoreOrders=ref(false)
async function moreOrders(){try{const data=await api(`orders/?page=${orderPage.value+1}${merchant.value?'&merchant=1':''}`);orders.value.push(...data.results);orderPage.value++;hasMoreOrders.value=!!data.next}catch{message.value='Não foi possível carregar mais pedidos.'}}
async function syncCatalog(){try{const data=await api('restaurants/');const list=data.results||data;restaurants.forEach(r=>r.closed=!list.some(remote=>remote.id===r.id));list.forEach(remote=>{const local=restaurants.find(r=>r.id===remote.id);if(local)Object.assign(local,{name:remote.name,products:remote.products.map(p=>({...p,price:Number(p.price)})),closed:false})});online.value=true}catch{online.value=false}}
async function loadProducts(){try{const data=await api('products/');merchantProducts.value=data.results||data}catch{message.value='Entre com a conta do lojista para gerenciar o cardápio.'}}
async function saveProduct(){try{await api('products/',{method:'POST',body:JSON.stringify({restaurant:merchantRestaurant.value,name:newName.value,price:newPrice.value,available:true})});newName.value='';newPrice.value='';await loadProducts();await syncCatalog()}catch{message.value='Confira restaurante, nome e preço do produto.'}}
async function toggleProduct(p){try{await api(`products/${p.id}/`,{method:'PATCH',body:JSON.stringify({available:!p.available,restaurant:p.restaurant})});await loadProducts();await syncCatalog()}catch{message.value='Não foi possível alterar o produto.'}}
function addConfigured(p,r){const options=(p.options||[]).filter(o=>(chosenOptions.value[p.id]||[]).includes(o.id));const key=p.id+':'+options.map(o=>o.id).sort().join(',');const item={...p,id:key,productId:p.id,optionIds:options.map(o=>o.id),name:p.name+(options.length?' + '+options.map(o=>o.name).join(', '):''),price:p.price+options.reduce((sum,o)=>sum+Number(o.price),0)};add(item,r)}
function locate(){
 if(locating.value)return
 locationError.value=''
 if(!window.isSecureContext){locationError.value='A localização exige HTTPS ou acesso por localhost.';return}
 if(!navigator.geolocation){locationError.value='Geolocalização indisponível neste navegador.';return}
 locating.value=true
 locatedStreet.value=''
 locatedArea.value=''
 locationStage.value='Buscando sua localização...'
 const previousAddress=address.value
 navigator.geolocation.getCurrentPosition(async p=>{
  coordinates.value={latitude:p.coords.latitude,longitude:p.coords.longitude}
  locationAccuracy.value=Math.round(p.coords.accuracy)
  locationStage.value='Buscando sua rua...'
  try{
   const result=await reverseGeocode(coordinates.value)
   locatedStreet.value=result.street
   locatedArea.value=result.area
   if(address.value===previousAddress)address.value=result.street
   message.value='Rua encontrada! Confira o endereço e complete o número.'
  }catch{
   locationError.value='Encontramos sua localização, mas não foi possível identificar a rua. Tente novamente ou preencha a rua e o número abaixo.'
  }finally{locating.value=false}
 },error=>{
  locating.value=false
  locationError.value=error.code===1?'Permissão negada. Abra as permissões deste site ao lado do endereço no navegador, permita Localização e tente novamente.':error.code===3?'A localização demorou para responder. Tente novamente.':'Não foi possível determinar sua localização. Confira o serviço de localização do dispositivo.'
 },{enableHighAccuracy:true,timeout:15000,maximumAge:60000})
}

onMounted(async()=>{await syncCatalog();catalogTimer=setInterval(syncCatalog,15000);if(token.value){await loadOrders();orders.value.filter(o=>o.status!=='delivered').forEach(track)}})
onUnmounted(()=>{clearInterval(catalogTimer);sockets.forEach(s=>s.close())})
</script>

<template>
 <header class="header"><div class="nav wrap"><a class="logo" href="#" @click.prevent="tab='Explorar'">rango<span>.io</span><i></i></a><div class="nav-divider"></div><button class="address" @click="addressOpen=true"><MapPin :size="19"/><span>Entregar em<small>{{address || locationLabel}}</small></span><ChevronDown :size="15"/></button><nav><button v-for="t in ['Explorar','Meus pedidos','Favoritos']" :class="{active:tab===t}" @click="tab=t;t==='Meus pedidos'&&loadOrders()">{{t}}</button></nav><button class="login" @click="loginOpen=true">{{token?'Minha conta':'Entrar'}} <ArrowUpRight :size="16"/></button><button class="bag-button" @click="drawer=true"><ShoppingBag :size="19"/><span>{{cart.count}}</span></button></div></header>
 <main class="wrap"><template v-if="tab==='Explorar'||tab==='Favoritos'">
 <div class="intro"><div><div class="eyebrow"><span></span> COMIDA BOA, PERTO DE VOCÊ</div><h1>Seu próximo favorito<br>está <em>logo ali.</em></h1><p>Do primeiro café à última fatia. Encontre seu rango.</p></div><div class="intro-note"><span>Feito para a sua fome.</span><svg width="62" height="32" viewBox="0 0 62 32"><path d="M2 4Q28 38 57 12M44 11L58 11L57 25" fill="none" stroke="#ef3038" stroke-width="2"/></svg></div></div>
 <section class="hero"><img :src="photo('photo-1568901346375-23c9450c58cd',1400)" alt="Hambúrguer artesanal com queijo e vegetais frescos"><div class="hero-shade"></div><div class="hero-content"><span class="hero-label">SEU RANGO, SEM COMPLICAÇÃO</span><h2>Deu fome?<br>A gente resolve.</h2><p>Os melhores sabores do bairro,<br>direto para a sua porta.</p><button @click="selected=restaurants[0]">Bora pedir <ArrowRight :size="18"/></button></div><div class="hero-sticker">primeiro pedido?<strong>vai de rango.</strong><span>Bom demais para deixar pra depois.</span></div><div class="hero-pagination"><b></b><i></i><i></i></div></section>
 <section class="discovery"><div class="search"><Search :size="20"/><input v-model="query" placeholder="O que vai matar sua fome hoje?" aria-label="Buscar restaurante"><kbd>⌕</kbd></div><div class="categories"><button v-for="[emoji,name] in categories" @click="category=name" :class="{chosen:category===name}"><span>{{emoji}}</span>{{name}}</button></div></section>
 <section class="restaurant-section"><div class="section-head"><div><div class="eyebrow subtle">BONS ENCONTROS COMEÇAM À MESA</div><h2>{{tab==='Favoritos'?'Seus favoritos':'Pertinho de você'}} <span>{{visible.length}} lugares para descobrir</span></h2></div><button class="sort" @click="filter=filter==='Melhor avaliação'?'':'Melhor avaliação'"><SlidersHorizontal :size="16"/>{{filter==='Melhor avaliação'?filter:'Ordenar'}}<ChevronDown :size="14"/></button></div><div class="filters"><button v-for="f in ['Entrega grátis','Até 30 min','Melhor avaliação']" :class="{selected:filter===f}" @click="filter=filter===f?'':f"><span>{{f==='Entrega grátis'?'✦':f==='Até 30 min'?'◷':'☆'}}</span>{{f}}<X v-if="filter===f" :size="12"/></button><span class="open-now"><i></i> Abertos agora</span></div>
 <div class="restaurant-grid"><article v-for="r in visible" :key="r.id" class="restaurant-card" @click="selected=r" tabindex="0" @keydown.enter="selected=r"><div class="card-image"><img :src="photo(r.image)" :alt="r.category+' de '+r.name" loading="lazy"><span class="tag" :class="{free:r.fee===0}">{{r.tag}}</span><button class="heart" :class="{loved:favorites.includes(r.id)}" @click.stop="favorites.includes(r.id)?favorites.splice(favorites.indexOf(r.id),1):favorites.push(r.id)" :aria-label="'Favoritar '+r.name"><Heart :size="18"/></button><div class="restaurant-monogram" :style="{background:r.color}">{{r.name.split(' ').map(w=>w[0]).filter(c=>c!=='&').slice(0,2).join('')}}<small>COZINHA AUTORAL</small></div></div><div class="card-details"><div class="card-title"><h3>{{r.name}}</h3><span><Star :size="13" fill="currentColor"/>{{r.rating}}</span></div><p>{{r.category}} <b>·</b> {{r.distance}} km de você</p><div class="card-bottom"><span><Clock :size="14"/>{{r.time}} min <b>·</b> <em :class="{freeText:!r.fee}">{{r.fee?money(r.fee):'Entrega grátis'}}</em></span><ArrowUpRight :size="17"/></div></div></article></div><div v-if="!visible.length" class="empty">Nenhum restaurante encontrado. Experimente outra categoria.</div></section>
 <section class="bottom-banner"><div class="banner-icon">✦</div><div><h3>Seu bairro tem muito sabor.</h3><p>Apoie os restaurantes locais. Descubra algo novo hoje.</p></div><button @click="category='Tudo';filter='';query='';tab='Explorar'">Explorar sabores <ArrowRight :size="17"/></button></section>
 </template>
 <section v-else class="orders-page"><div class="section-head"><h1>{{merchant?'Painel do restaurante':'Meus pedidos'}}</h1><button class="sort" @click="merchant=!merchant;loadOrders();merchant&&loadProducts()"><Store :size="17"/>{{merchant?'Ver como cliente':'Painel do restaurante'}}</button></div><p class="muted">Cada etapa do seu rango, em tempo real.</p><section v-if="merchant" class="order-card"><h3>Seu cardápio</h3><form class="product-form" @submit.prevent="saveProduct"><label>Restaurante<select v-model="merchantRestaurant"><option v-for="r in restaurants" :value="r.id">{{r.name}}</option></select></label><label>Nome<input v-model="newName" required></label><label>Preço<input v-model="newPrice" type="number" min="0.01" step="0.01" required></label><button class="primary">Cadastrar produto</button></form><div class="merchant-product" v-for="p in merchantProducts"><span>{{p.name}} · {{money(Number(p.price))}}</span><button class="sort" @click="toggleProduct(p)">{{p.available?'Pausar':'Disponibilizar'}}</button></div></section><div v-if="!token" class="empty"><ShoppingBag :size="36"/><h2>Entre para acompanhar seus pedidos</h2><p>Seu histórico fica disponível na sua conta.</p><button class="primary" @click="loginOpen=true">Entrar na conta</button></div><div v-else-if="ordersLoading" class="empty" role="status">Carregando seus pedidos...</div><div v-else-if="ordersError" class="empty" role="alert"><h2>Não conseguimos carregar seus pedidos</h2><p>{{ordersError}}</p><button class="primary" @click="loadOrders">Tentar novamente</button></div><div v-else-if="!orders.length" class="empty"><ShoppingBag :size="36"/><h2>{{merchant?'Nenhum pedido recebido ainda':'Você ainda não fez seu primeiro pedido'}}</h2><p>{{merchant?'Novos pedidos aparecerão aqui.':'Que tal descobrir seu próximo rango favorito?'}}</p><button v-if="!merchant" class="primary" @click="tab='Explorar'">Explorar restaurantes</button></div><article v-for="o in orders" class="order-card"><div class="section-head"><h3>Pedido #{{o.id}}</h3><b>{{money(Number(o.total))}}</b></div><p>{{o.address}}</p><div class="progress"><span v-for="(label,key) in statusLabels" :class="{done:Object.keys(statusLabels).indexOf(key)<=Object.keys(statusLabels).indexOf(o.status)}"><Check :size="16"/>{{label}}</span></div><button class="primary" v-if="merchant&&o.status!=='delivered'" @click="changeStatus(o)">Avançar pedido</button><button class="sort" v-else @click="reorder(o)">Pedir novamente</button></article><button v-if="hasMoreOrders" class="sort" @click="moreOrders">Carregar mais pedidos</button></section>
 <footer><a class="logo" href="#">rango<span>.io</span><i></i></a><span>Comida boa conecta. © {{new Date().getFullYear()}} rango.io</span><span class="footer-status"><i :class="{connected:online}"></i>{{online?'Conectado à cozinha':'Explore o cardápio · modo demonstração'}}</span></footer></main>
 <div v-if="selected" class="overlay" @click.self="selected=null"><section class="modal menu-modal"><button class="close" @click="selected=null"><X/></button><img class="menu-cover" :src="photo(selected.image)" :alt="selected.name"><div class="modal-body"><span class="eyebrow">{{selected.category}} · {{selected.time}} MIN</span><h2>{{selected.name}}</h2><p class="muted">{{selected.description}}</p><article class="menu-product" v-for="p in selected.products.filter(p=>p.available!==false)"><div><h3>{{p.name}}</h3><p>{{p.description}}</p><b>{{money(p.price)}}</b><label class="option-line" v-for="o in (p.options||[]).filter(o=>o.available)"><input type="checkbox" :value="o.id" :checked="(chosenOptions[p.id]||[]).includes(o.id)" @change="chosenOptions[p.id]=$event.target.checked?[...(chosenOptions[p.id]||[]),o.id]:(chosenOptions[p.id]||[]).filter(id=>id!==o.id)">{{o.name}} + {{money(Number(o.price))}}</label></div><button class="add" @click="addConfigured(p,selected)" :aria-label="'Adicionar '+p.name"><Plus :size="20"/></button></article><button class="primary full" @click="selected=null;drawer=true">Ver sacola · {{cart.count}} itens <ArrowRight :size="18"/></button></div></section></div>
 <div v-if="drawer" class="overlay" @click.self="drawer=false"><aside class="drawer"><div class="section-head"><h2>Sua sacola <span>({{cart.count}})</span></h2><button class="icon" @click="drawer=false"><X/></button></div><p class="muted">Seu próximo momento gostoso.</p><div v-if="!cart.count" class="empty">A sacola está esperando seu rango.</div><article v-for="i in cart.items" class="cart-item"><div><h3>{{i.name}}</h3><b>{{money(i.price*i.quantity)}}</b></div><div class="quantity"><button @click="cart.change(i.id,-1)"><Minus :size="14"/></button>{{i.quantity}}<button @click="cart.change(i.id,1)"><Plus :size="14"/></button></div></article><template v-if="cart.count"><div class="delivery-note"><MapPin :size="20"/><div>Entregar em <b>{{address}}</b><small>O frete final é calculado pela API com a distância.</small></div></div><div class="cart-total"><span>Subtotal</span><strong>{{money(cart.total)}}</strong></div><button class="primary full" @click="checkout">Confirmar pedido <ArrowRight :size="18"/></button></template></aside></div>
 <div v-if="addressOpen||loginOpen||pending" class="overlay" @click.self="addressOpen=false;loginOpen=false;pending=null"><section class="modal small-modal"><button class="close" @click="addressOpen=false;loginOpen=false;pending=null"><X/></button><form v-if="addressOpen" @submit.prevent="saveAddress"><MapPin class="orange"/><h2>Onde vai ser o rango?</h2><button type="button" class="primary full" :disabled="locating" :aria-busy="locating" @click="locate"><MapPin :size="18"/>{{locating?locationStage:'Usar minha localização'}}</button><p v-if="locationError" class="login-error" role="alert">{{locationError}}</p><div v-if="coordinates" class="location-result"><strong>{{locatedStreet || 'Localização encontrada'}}</strong><p v-if="locatedArea">{{locatedArea}}</p><p>Latitude {{coordinates.latitude.toFixed(5)}} · Longitude {{coordinates.longitude.toFixed(5)}}</p><p>Precisão aproximada: {{locationAccuracy}} m</p><a :href="`https://www.openstreetmap.org/?mlat=${coordinates.latitude}&mlon=${coordinates.longitude}#map=17/${coordinates.latitude}/${coordinates.longitude}`" target="_blank" rel="noopener noreferrer">Ver minha posição no mapa ↗</a></div><p class="muted location-help">Buscamos sua rua a partir da localização do dispositivo. Confira o endereço e complete o número para a entrega.</p><label>Endereço de entrega<input v-model="address" required placeholder="Rua e número"></label><p v-if="locatedStreet" class="muted location-help">Endereço aproximado · © <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap</a></p><button class="primary full" :disabled="locating">Salvar endereço</button></form><div v-else-if="loginOpen&&token"><h2>{{accountName ? `Olá, ${accountName}!` : 'Sua conta está conectada'}}</h2><p class="muted">Você já pode pedir e acompanhar seu rango.</p><button type="button" class="primary full" @click="loginOpen=false;tab='Meus pedidos';loadOrders()">Ver meus pedidos</button><button type="button" class="sort full" @click="logout">Sair da conta <LogOut :size="16"/></button></div><form v-else-if="loginOpen" @submit.prevent="login"><h2>Que bom te ver por aqui.</h2><p class="muted">Entre para pedir e acompanhar seu rango.</p><label>Usuário<input v-model="email" autocomplete="username" required></label><label>Senha<input v-model="password" type="password" autocomplete="current-password" required></label><p v-if="loginError" class="login-error" role="alert">{{loginError}}</p><button type="submit" class="primary full" :disabled="loggingIn" :aria-busy="loggingIn">{{loggingIn?'Entrando...':'Entrar'}} <ArrowRight v-if="!loggingIn" :size="17"/></button><button v-if="token" type="button" class="sort full" @click="token='';sessionStorage.removeItem('token');sessionStorage.removeItem('refresh');sockets.forEach(s=>s.close());orders=[];loginOpen=false">Sair da conta <LogOut :size="16"/></button></form><div v-else><h2>Um restaurante por vez</h2><p class="muted">Quer esvaziar a sacola e começar um pedido em {{pending.r.name}}?</p><button class="primary full" @click="replace">Começar nova sacola</button><button class="sort full" @click="pending=null">Manter minha sacola</button></div></section></div>
 <div v-if="message" class="toast" role="status" @click="message=''">{{message}}<button class="icon" @click="message=''"><X :size="16"/></button></div>
</template>
